insert into ETR_CASH_POSITION (PORTFOLIO_ID, ACCT_ID, HODING_TYPE, CDATE, CCY, AMOUNT, CHL_FINPROD_ID, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME ) VALUES targetTable.PORTFOLIO_ID, targetTable.ACCT_ID, HODING_TYPE, #{batchDate,jdbcType=DATE}, targetTable.CCY, SUM(targetTable.AMOUNT), targetTable.CHL_FINPROD_ID, 'system', null, NOW(), 'system', NOW() FROM ( SELECT PORTFOLIO_ID, ACCT_ID, CCY, AMOUNT, CHL_FINPROD_ID, HODING_TYPE FROM ETR_CASH_POSITION WHERE HODING_TYPE IN (#{POSITION_TYPE_E01,jdbcType=VARCHAR},#{POSITION_TYPE_E02,jdbcType=VARCHAR}) and CDATE = #{lastDate,jdbcType=DATE}
and (
)
union all SELECT PORTFOLIO_ID, ACCT_ID, CCY, SUM(AMOUNT) as AMOUNT, CHL_FINPROD_ID, HODING_TYPE FROM ETR_CASH_POSITION_FLOW WHERE HODING_TYPE IN (#{POSITION_TYPE_E01,jdbcType=VARCHAR},#{POSITION_TYPE_E02,jdbcType=VARCHAR}) and CDATE = #{batchDate,jdbcType=DATE}
and (
)
GROUP BY PORTFOLIO_ID, ACCT_ID, CCY, CHL_FINPROD_ID, HODING_TYPE ) targetTable group by targetTable.PORTFOLIO_ID, targetTable.ACCT_ID, targetTable.CCY, targetTable.CHL_FINPROD_ID, targetTable.HODING_TYPE
